package com.chargeshare.service;
import com.chargeshare.dto.BookingRequest;import com.chargeshare.model.*;import com.chargeshare.repository.*;import com.chargeshare.security.*;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.util.*;
@Service
public class BookingService {
 private final BookingRepository repo;private final LocationService locations;private final PaymentRepository payments;
 public BookingService(BookingRepository repo,LocationService locations,PaymentRepository payments){this.repo=repo;this.locations=locations;this.payments=payments;}
 public List<Booking> all(String email){AuthSession u=CurrentUser.get();if(u.role()==Role.ADMIN)return email==null||email.isBlank()?repo.findAll():repo.findByCustomerEmailIgnoreCaseOrderByCreatedAtDesc(email);if(u.role()==Role.USER)return repo.findByCustomerEmailIgnoreCaseOrderByCreatedAtDesc(u.email());return repo.findAll().stream().filter(b->b.getLocation().getHostEmail()!=null&&b.getLocation().getHostEmail().equalsIgnoreCase(u.email())).sorted(Comparator.comparing(Booking::getCreatedAt).reversed()).toList();}
 public List<Booking> forLocation(Long id){AuthSession u=CurrentUser.get();ChargingLocation l=locations.get(id);if(u.role()!=Role.ADMIN&&!(u.role()==Role.HOST&&u.email().equalsIgnoreCase(l.getHostEmail())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot view bookings for this location");return repo.findByLocationIdOrderByCreatedAtDesc(id);}
 public Booking get(Long id){Booking b=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));checkView(b);return b;}
 private void checkView(Booking b){AuthSession u=CurrentUser.get();if(u.role()==Role.ADMIN)return;if(u.role()==Role.USER&&b.getCustomerEmail().equalsIgnoreCase(u.email()))return;if(u.role()==Role.HOST&&b.getLocation().getHostEmail()!=null&&b.getLocation().getHostEmail().equalsIgnoreCase(u.email()))return;throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot access this booking");}
 public Booking create(BookingRequest r){AuthSession u=CurrentUser.require(Role.USER);ChargingLocation l=locations.get(r.locationId());if(l.getAvailableChargers()<1||!l.isHostAvailable())throw new ResponseStatusException(HttpStatus.CONFLICT,"This host is not currently available");Booking b=new Booking();apply(b,r,l);b.setStatus(BookingStatus.PENDING);b.setPaymentStatus(PaymentStatus.UNPAID);return repo.save(b);}
 public Booking update(Long id,BookingRequest r){AuthSession u=CurrentUser.require(Role.USER,Role.ADMIN);Booking b=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(u.role()==Role.USER&&!b.getCustomerEmail().equalsIgnoreCase(u.email()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only modify your own bookings");if(b.getStatus()!=BookingStatus.PENDING&&b.getStatus()!=BookingStatus.ACCEPTED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending or accepted bookings can be edited");if(b.getPaymentStatus()==PaymentStatus.PAID)throw new ResponseStatusException(HttpStatus.CONFLICT,"Paid bookings cannot be modified in this demo");ChargingLocation l=locations.get(r.locationId());apply(b,r,l);b.setStatus(BookingStatus.PENDING);return repo.save(b);}
 private void apply(Booking b,BookingRequest r,ChargingLocation l){b.setLocation(l);b.setCustomerName(r.customerName().trim());b.setCustomerEmail(r.customerEmail().trim().toLowerCase());b.setStartTime(r.startTime());b.setEnergyKwh(r.energyKwh());b.setTotalPrice(Math.round(r.energyKwh()*l.getPricePerKwh()*100.0)/100.0);}
 @Transactional
 public Booking cancel(Long id){AuthSession u=CurrentUser.require(Role.USER,Role.HOST,Role.ADMIN);Booking b=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(u.role()==Role.USER&&!b.getCustomerEmail().equalsIgnoreCase(u.email()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only cancel your own bookings");if(u.role()==Role.HOST&&(b.getLocation().getHostEmail()==null||!b.getLocation().getHostEmail().equalsIgnoreCase(u.email())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only cancel bookings for your locations");if(b.getStatus()==BookingStatus.CANCELLED||b.getStatus()==BookingStatus.REJECTED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Booking is already closed");b.setStatus(BookingStatus.CANCELLED);if(b.getPaymentStatus()==PaymentStatus.PAID){b.setPaymentStatus(PaymentStatus.REFUNDED);payments.findByBookingId(id).ifPresent(p->{p.setStatus(PaymentStatus.REFUNDED);payments.save(p);});}return repo.save(b);}
 public Booking respond(Long id,boolean accept){AuthSession u=CurrentUser.require(Role.HOST,Role.ADMIN);Booking b=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Booking not found"));if(u.role()==Role.HOST&&(b.getLocation().getHostEmail()==null||!b.getLocation().getHostEmail().equalsIgnoreCase(u.email())))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only respond to bookings for your locations");if(b.getStatus()!=BookingStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending bookings can be accepted or rejected");b.setStatus(accept?BookingStatus.ACCEPTED:BookingStatus.REJECTED);return repo.save(b);}
}
